import * as React from "react";

export type ArcadeJoystickIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ArcadeJoystickIcon({ size = 20, ...props }: ArcadeJoystickIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="9" cy="15" r="1.2" /><path d="M9 15v-4M9 11a1.8 1.8 0 1 0 .1 0M15 13.5h3" />
